"""Locate a usable fastText engine and expose train()/test() without touching
the authors' code.

Order of preference (see assumption A14):
  1. an already importable `fasttext` module (the official Python binding of the
     authors' C++ trainer, e.g. installed as the prebuilt fasttext-wheel 0.9.2);
  2. `pip install fasttext-wheel` (same thing, fetched on demand);
  3. a native build of the cloned repo (`make` / `pip install .`) if a C++
     toolchain exists;
  4. last resort: the authors' PyTorch EmbeddingBag re-implementation
     (repo/python/doc/examples/FastTextEmbeddingBag.py) - this is a
     re-implementation, so the verdict ceiling drops to partially_reproduced.
"""

import os
import subprocess
import sys

WORKDIR = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.join(WORKDIR, "repo")

_state = None


def _try_import():
    import fasttext  # noqa: F401
    return fasttext


def _pip_install(pkg):
    try:
        subprocess.run([sys.executable, "-m", "pip", "install", pkg],
                       check=True, timeout=300,
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return True
    except Exception:
        return False


def _native_binary():
    """Build the authors' C++ binary with make/cmake if a toolchain is present."""
    exe = os.path.join(REPO, "fasttext.exe" if os.name == "nt" else "fasttext")
    if os.path.isfile(exe):
        return exe
    for tool in ("make",):
        if subprocess.run(["where", tool], shell=False, capture_output=True).returncode != 0:
            return None
    try:
        subprocess.run(["make", "-C", REPO], check=True, timeout=1800,
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        return None
    return exe if os.path.isfile(exe) else None


def engine():
    """Return dict(name, fasttext, binary, verdict_ceiling, note)."""
    global _state
    if _state is not None:
        return _state
    try:
        ft = _try_import()
        _state = {"name": "fasttext python binding (authors' C++ trainer)",
                  "fasttext": ft, "binary": None, "verdict_ceiling": "reproduced",
                  "note": "import fasttext -> %s" % ft.__file__}
        return _state
    except ImportError:
        pass
    if _pip_install("fasttext-wheel"):
        try:
            ft = _try_import()
            _state = {"name": "fasttext-wheel (prebuilt authors' C++ trainer)",
                      "fasttext": ft, "binary": None, "verdict_ceiling": "reproduced",
                      "note": "pip install fasttext-wheel at run time"}
            return _state
        except ImportError:
            pass
    exe = _native_binary()
    if exe:
        _state = {"name": "native build of repo/ (authors' C++ binary)",
                  "fasttext": None, "binary": exe, "verdict_ceiling": "reproduced",
                  "note": exe}
        return _state
    raise RuntimeError(
        "no fastText engine available: `import fasttext` failed, pip install of "
        "fasttext-wheel failed and no C++ toolchain to build repo/. The planned "
        "EmbeddingBag fallback would be a re-implementation; refusing to silently "
        "downgrade the reproduction.")


def version():
    eng = engine()
    if eng["fasttext"] is not None:
        import importlib.metadata as md

        for pkg in ("fasttext", "fasttext-wheel", "fasttext_pybind"):
            try:
                return "%s==%s" % (pkg, md.version(pkg))
            except Exception:
                pass
        return "fasttext (version unknown)"
    out = subprocess.run([eng["binary"], "--version"], capture_output=True, text=True)
    return (out.stdout + out.stderr).strip()


def train(input_file, output_file, **kwargs):
    """Train and return an opaque model handle."""
    eng = engine()
    kwargs.setdefault("verbose", 0)
    if eng["fasttext"] is not None:
        m = eng["fasttext"].train_supervised(input=input_file, output_prefix=output_file,
                                             **kwargs)
        return {"kind": "python", "model": m, "path": output_file + ".bin"}
    cmd = [eng["binary"], "supervised", "-input", input_file, "-output", output_file]
    flag = {"dim": "dim", "epoch": "epoch", "lr": "lr", "wordNgrams": "wordNgrams",
