            "loss": "loss", "minn": "minn", "maxn": "maxn", "seed": "seed",
            "lrUpdateRate": "lrUpdateRate"}
    for k, v in kwargs.items():
        if k == "verbose":
            continue
        if k not in flag:
            raise TypeError("unknown training argument %r" % k)
        cmd += ["-" + flag[k], str(v)]
    subprocess.run(cmd, check=True, capture_output=True, text=True)
    return {"kind": "cli", "model": None, "path": output_file + ".bin"}


